script:
if doc.docstatus == 2:
    todo_docs = frappe.get_all("ToDo",filters={"reference_name":doc.name, "status":"Open"},fields=["name"])

    for todo in todo_docs:
        frappe.db.set_value("ToDo",todo.name,"status","Closed")

if doc.estimated_cost >50000:
    doc.status = "Pending Approval"
else:
    doc.status = "Approved"
